<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
require dirname(__DIR__).'/app/bootstrap.php';
$base=rtrim(cfg()['base_url'],'/');$assets=json_decode(file_get_contents(dirname(__DIR__).'/app/giftcards-assets.json'),true,512,JSON_THROW_ON_ERROR);
try{foreach(['/giftcards/','/api/gift/config/',$assets['entry'],$assets['style']] as $path){$ch=curl_init($base.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_FOLLOWLOCATION=>false]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($body===false||$status!==200)throw new RuntimeException('Не прошла HTTPS-проверка '.$path);if($path==='/api/gift/config/'){$d=json_decode($body,true,512,JSON_THROW_ON_ERROR);if(($d['mode']??'')!=='live'||!isset($d['offer']['hash']))throw new RuntimeException('Получен ответ другой версии API');}if($path==='/giftcards/'&&(!str_contains($body,'pina-runtime')||!str_contains($body,'live-app.js')))throw new RuntimeException('Получен интерфейс другой версии');if(str_ends_with($path,'.js')&&!hash_equals(hash('sha256',file_get_contents(dirname(__DIR__).'/dist'.$path)),hash('sha256',$body)))throw new RuntimeException('Не совпадает версия JS');}echo "HTTPS, рабочий режим интерфейса, версия API и контрольная сумма JS проверены.\n";}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
